const r = await tools.exec_command({cmd:"cat > "$STAMPED_JUDGE_OUTPUT/verify_manifest.py" <<'PY'
import hashlib, json, os, pathlib, sys
manifest=json.load(open(os.environ['STAMPED_DELIVERY_MANIFEST']))
root=pathlib.Path(os.environ['STAMPED_JUDGE_TARGET'])
entries=manifest.get('entries', [])
problems=[]
checked=0
for e in entries:
    rel=e['path']
    if rel.startswith('content/workspace/'):
        rel=rel[len('content/workspace/'):]
    else:
        continue
    p=root/rel
    kind=e.get('kind')
    if not p.exists() and not p.is_symlink():
        problems.append({'path':rel,'problem':'missing'}); continue
    if kind=='directory':
        if not p.is_dir(): problems.append({'path':rel,'problem':'not-directory'})
        checked+=1
    elif kind in ('file','symlink'):
        if kind=='symlink' and not p.is_symlink():
            problems.append({'path':rel,'problem':'not-symlink'}); continue
        if kind=='file' and not p.is_file():
            problems.append({'path':rel,'problem':'not-file'}); continue
        actual=hashlib.sha256(os.readlink(p).encode() if p.is_symlink() else p.read_bytes()).hexdigest()
        if actual != e.get('sha256'): problems.append({'path':rel,'problem':'sha256','expected':e.get('sha256'),'actual':actual})
        if e.get('size') is not None and p.lstat().st_size != e['size']: problems.append({'path':rel,'problem':'size','expected':e['size'],'actual':p.lstat().st_size})
        checked+=1
# Enumerate filesystem paths (including ignored/untracked), excluding only the actual .git internals from extra check? manifest should include them too.
known=set()
for e in entries:
    rel=e['path']
    if rel.startswith('content/workspace/'): known.add(rel[len('content/workspace/'):])
actual=set()
for d, dirs, files in os.walk(root, followlinks=False):
    for n in dirs+files:
        p=pathlib.Path(d)/n
        actual.add(p.relative_to(root).as_posix())
        if p.is_symlink():
            # don't traverse pointer
            if n in dirs: dirs.remove(n)
extra=sorted(actual-known)
missing=sorted(known-actual)
result={'manifest_entries_checked':checked,'target_paths':len(actual),'manifest_workspace_paths':len(known),'problems':problems,'extra_paths':extra,'missing_paths':missing}
print(json.dumps(result,indent=2))
PY
